const uno = part("uno", "arduino-uno");
const r = part("r", "resistor", { value: 220 });
const led = part("led", "led", { color: "red" });
connect(uno.pin("9"), r.pin("1"), { id: "drive", role: "signal" });
connect(r.pin("2"), led.pin("A"), { id: "ledNode", role: "signal" });
ground(uno.pin("GND.1"), led.pin("C"));
